namespace PZ3D {
 static class BuddyTakeoverTests {
  const string Dirty="{\"vmArgs\":[\"-Xmx8g\",\"-agentlib:zbNative\",\"-javaagent:ZombieBuddy.jar\"],\"custom\":42}";
  const string Vdf="\"UserLocalConfigStore\" { \"Software\" { \"Valve\" { \"Steam\" { \"apps\" { \"108600\" { \"LaunchOptions\" \"-agentlib:zbNative -password secretFixture\" } \"999\" { \"LaunchOptions\" \"-agentlib:zbNative\" } } } } } \"unrelated\" \"old\" }";
  static void Check(bool value,string label){if(!value)throw new Exception("FAIL: "+label);Console.WriteLine("PASS: "+label);}
  sealed class Fixture {
   internal Engine E; internal Fake OS; internal string Root,VdfPath;
   internal Fixture(bool steam=false,string root=null){Root=root??Path.Combine(LauncherTestPaths.Root,"buddy-takeover-"+Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(Root,"game"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true);OS=new Fake(this){Steam=steam};VdfPath=Path.Combine(Root,"steam","userdata","12345","config","localconfig.vdf");if(root!=null)return;Directory.CreateDirectory(E.Game);File.WriteAllText(E.Config,Dirty,new UTF8Encoding(true));File.WriteAllText(Path.Combine(E.Game,"ProjectZomboid64.exe"),"fixture");Directory.CreateDirectory(Path.GetDirectoryName(VdfPath));File.WriteAllText(VdfPath,Vdf,new UTF8Encoding(false));File.WriteAllText(Path.Combine(Root,"steam","steam.exe"),"fixture only");}
   internal BuddyTakeoverPreview Preview(){return BuddyTakeover.Preview(E,OS);}
   internal BuddyTakeoverResult Apply(BuddyTakeoverPreview p,bool yes=true,bool exit=true,CancellationToken cancel=default(CancellationToken)){return BuddyTakeover.Apply(E,p.stamp,yes,exit,null,cancel,OS);}
  }
  sealed class Fake:BuddyTakeoverEnvironment {
   internal Fixture F; internal bool Unknown,Steam,Running=true,Game,Timeout,ReopenFail,Crash;
   internal int Shutdowns,Reopens,Writes,FailWrite,CrashAt=1;internal long Clock,Birth=100;internal uint Account=12345;
   internal Action OnShutdown,OnWait,OnReplace;
   internal Action<string,string> OnMoveAbsent;
   internal Fake(Fixture f){F=f;}
   internal override BuddySteamIdentity Capture(){return new BuddySteamIdentity(Unknown?new SteamLaunchOptionsSnapshot(null,0,null,SteamLaunchOptionsState.UnknownIdentity):Steam?SteamLaunchOptions.Read(Path.Combine(F.Root,"steam"),Account):SteamLaunchOptions.Unavailable(),Steam?77:0,Steam?Birth:0,Steam?Path.Combine(F.Root,"steam","steam.exe"):null);}
   internal override BuddySteamState Inspect(BuddySteamIdentity bound){if(bound.Birth!=Birth||bound.Options.Account!=Account)return BuddySteamState.Changed;return Running?BuddySteamState.Running:BuddySteamState.Exited;}
   internal override bool GameRunning(string game){return Game;}
   internal override void Shutdown(BuddySteamIdentity bound){Check(bound.Pid==77&&bound.Executable==Path.Combine(F.Root,"steam","steam.exe"),"shutdown binds selected client");Shutdowns++;if(OnShutdown!=null)OnShutdown();if(!Timeout)Running=false;}
   internal override bool Reopen(BuddySteamIdentity bound){Reopens++;return !ReopenFail;}
   internal override long Milliseconds {get{return Clock;}}
   internal override void Wait(int ms){Clock+=ms;if(OnWait!=null)OnWait();}
   internal override void Replace(string temp,string target,string displaced){Writes++;if(OnReplace!=null)OnReplace();if(FailWrite==Writes)throw new IOException("secretFixture must not leak");base.Replace(temp,target,displaced);if(Crash&&Writes==CrashAt)Environment.Exit(73);}
   internal override bool RestoreOwned(string candidate,string target,string retired,byte[] expected){Writes++;if(OnReplace!=null)OnReplace();return base.RestoreOwned(candidate,target,retired,expected);}
   internal override void MoveAbsent(string source,string target){if(OnMoveAbsent!=null)OnMoveAbsent(source,target);base.MoveAbsent(source,target);}
  }
  static void UnknownScope(){var f=new Fixture();f.OS.Unknown=true;byte[] vdf=File.ReadAllBytes(f.VdfPath);var p=f.Preview();Check(p.supported&&p.hasConflicts&&!p.knownIdentity&&p.scope=="localOnly"&&p.scanState=="conflicts"&&p.steamState=="unverified","unverified Steam still scans local conflicts");var r=f.Apply(p);Check(r.cleanupCompleted&&!r.steamVerified&&r.scope=="localOnly"&&f.OS.Shutdowns==0&&vdf.SequenceEqual(File.ReadAllBytes(f.VdfPath)),"local-only cleanup leaves unverified Steam untouched");}
  static void Consent(){var f=new Fixture(true);byte[] before=File.ReadAllBytes(f.E.Config);var p=f.Preview();Check(p.supported&&p.requiresSteamExit&&p.knownIdentity,"native preview identifies exact app conflict");Check(!Directory.Exists(f.E.Data),"preview has no file effects");Check(f.Apply(p,false).status=="cancelled","false confirmation cancels");var c=new CancellationToken(true);Check(f.Apply(p,true,true,c).status=="cancelled","pre-cancel returns cancelled");Check(f.Apply(p,true,false).status=="confirmationRequired","exit has separate consent");Check(!Directory.Exists(f.E.Data)&&before.SequenceEqual(File.ReadAllBytes(f.E.Config))&&f.OS.Shutdowns==0&&f.OS.Reopens==0,"no consent means zero write shutdown or reopen");}
  static void GameOnly(){var f=new Fixture();string bat=Path.Combine(f.E.Game,"ProjectZomboid32.bat");File.WriteAllText(bat,"java -agentlib:zbNative -Xmx2g -jar game.jar --keep\r\n",new UnicodeEncoding(false,true));var p=f.Preview();var r=f.Apply(p);Check(r.cleanupCompleted&&r.status=="completed"&&!r.componentInstallCompleted&&!r.steamVerified,"cleanup distinct from Steam verification and install");Check(File.ReadAllText(f.E.Config)=="{\"vmArgs\":[\"-Xmx8g\",\"-agentlib:zbNative\"],\"custom\":42}","known JSON cleaned and normal native plus heap preserved");Check(File.ReadAllText(bat)=="java -Xmx2g -jar game.jar --keep\r\n"&&File.ReadAllBytes(bat).Take(2).SequenceEqual(new byte[]{255,254}),"BAT only removes known agent preserving UTF16 BOM");Check(f.OS.Shutdowns==0&&f.OS.Reopens==0&&!BuddyTakeover.Pending(f.E),"game only never exits Steam and clears pending");}
  static void Flush(){var f=new Fixture(true);f.OS.OnShutdown=()=>File.WriteAllText(f.VdfPath,Vdf.Replace("\"old\"","\"flushed\""),new UTF8Encoding(false));var r=f.Apply(f.Preview());Check(r.cleanupCompleted&&r.steamVerified&&r.steamExitRequested&&r.steamReopenRequested,"Steam cleanup reports actual phases");Check(File.ReadAllText(f.VdfPath)==Vdf.Replace("-agentlib:zbNative -password","-password").Replace("\"old\"","\"flushed\""),"post-exit fresh VDF retains unrelated flush and other app");string dto=new JavaScriptSerializer().Serialize(new object[]{f.Preview(),r,BuddyTakeover.Recovery(f.E,f.OS)});string logs=string.Join("",Directory.GetFiles(Path.Combine(f.E.Data,"diagnostics")).Select(File.ReadAllText));Check(!dto.Contains("secretFixture")&&!dto.Contains("12345")&&!logs.Contains("secretFixture")&&!logs.Contains("12345"),"safe DTO and diagnostics never disclose secrets or account");}
  static void Stale(){foreach(string kind in new[]{"game","field","account","birth","path"}){var f=new Fixture(true);var p=f.Preview();if(kind=="game")File.AppendAllText(f.E.Config," ");if(kind=="field")File.WriteAllText(f.VdfPath,Vdf.Replace("secretFixture","changed"));if(kind=="account")f.OS.Account=54321;if(kind=="birth")f.OS.Birth++;if(kind=="path")f.E.Game=Path.Combine(f.Root,"other");var r=f.Apply(p);Check(!r.cleanupCompleted&&f.OS.Shutdowns==0&&f.OS.Writes==0,"stale "+kind+" refuses before process or file effects");}}
  static void ExitFailure(){foreach(string kind in new[]{"timeout","target","account","cancel"}){var f=new Fixture(true);byte[] before=File.ReadAllBytes(f.E.Config),vdf=File.ReadAllBytes(f.VdfPath);var c=new CancellationTokenSource();if(kind=="timeout"){f.OS.Timeout=true;}if(kind=="target")f.OS.OnShutdown=()=>File.WriteAllText(f.VdfPath,Vdf.Replace("secretFixture","new-value"));if(kind=="account")f.OS.OnShutdown=()=>f.OS.Account++;if(kind=="game")f.OS.OnShutdown=()=>f.OS.Game=true;if(kind=="cancel"){f.OS.Timeout=true;f.OS.OnWait=()=>c.Cancel();}var r=f.Apply(f.Preview(),true,true,c.Token);Check(!r.cleanupCompleted&&before.SequenceEqual(File.ReadAllBytes(f.E.Config))&&f.OS.Writes==0,"exit boundary "+kind+" cannot write");Check(f.OS.Clock<=30000&&f.OS.Reopens==1,"bounded exit and reopen after requested "+kind);}}
  static void Guards(){foreach(string kind in new[]{"game","session","maintenance","unsupported"}){var f=new Fixture();if(kind=="game")f.OS.Game=true;if(kind=="session"){Directory.CreateDirectory(Path.GetDirectoryName(f.E.Mods));File.WriteAllText(f.E.Mods,"VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n");File.WriteAllText(f.E.Config,"{\"vmArgs\":[]}");LaunchProfiles.Stage(f.E,new ProfileLaunchRequest{Kind="server",Host="127.0.0.1",Port=16261,Username="fixture"});File.WriteAllText(f.E.Config,Dirty);}if(kind=="maintenance"){Directory.CreateDirectory(f.E.Data);File.WriteAllText(Path.Combine(f.E.Data,"workshop-rebuild.pending"),"fixture");}if(kind=="unsupported")File.WriteAllText(Path.Combine(f.E.Game,"ProjectZomboid64.bat"),"if 1==1 (\r\njava -agentlib:zbNative -jar game.jar\r\n)\r\n");var p=f.Preview();if(kind=="game"||kind=="session")Check(p.supported&&f.Apply(p).cleanupCompleted,"configuration takeover permits "+kind);else Check(!p.supported&&!f.Apply(p).cleanupCompleted&&f.OS.Writes==0&&f.OS.Shutdowns==0,"preflight refuses "+kind);}}
  static void Rollback(){foreach(bool outside in new[]{false,true}){var f=new Fixture(true);byte[] before=File.ReadAllBytes(f.E.Config);f.OS.FailWrite=2;f.OS.OnReplace=()=>{if(outside&&f.OS.Writes==2)File.WriteAllText(f.E.Config,"external-owner-edit");};var r=f.Apply(f.Preview());Check(!r.cleanupCompleted&&r.recoveryPending==outside,"partial write reports rollback or conflict");Check(outside?File.ReadAllText(f.E.Config)=="external-owner-edit":before.SequenceEqual(File.ReadAllBytes(f.E.Config)),"rollback restores only own exact bytes; external edits survive");Check(File.ReadAllText(f.VdfPath)==Vdf&&f.OS.Reopens==1,"failed batch retains unwritten VDF and reopens");string[] backups=Directory.GetFiles(Path.Combine(f.E.Data,"backups"),"*.before",SearchOption.AllDirectories);Check(backups.Any(p=>File.ReadAllBytes(p).SequenceEqual(before)),"private backup retains exact original BOM bytes");foreach(string b in backups){var acl=File.GetAccessControl(b);var user=WindowsIdentity.GetCurrent().User;Check(acl.AreAccessRulesProtected&&acl.GetAccessRules(true,true,typeof(SecurityIdentifier)).Cast<FileSystemAccessRule>().All(a=>a.IdentityReference.Equals(user)),"backup ACL restricted to owner");}if(outside){bool refused=false;try{f.E.Guard();}catch{refused=true;}Check(refused&&LauncherLaunch.Reason(f.E,false,false)!="","pending recovery guards ordinary modifications and launch");var recovery=BuddyTakeover.Recovery(new Engine(f.E.Game,f.E.User,f.E.Data,true),f.OS);Check(recovery.pending&&!recovery.supported,"fresh service detects external recovery conflict without writing");}}}
  static void Reopen(){var f=new Fixture(true);f.OS.ReopenFail=true;var r=f.Apply(f.Preview());Check(r.cleanupCompleted&&!r.steamReopenRequested&&r.status=="partial"&&!r.componentInstallCompleted,"reopen failure keeps honest completed cleanup partial result");}
  static void Defaults(){var f=new Fixture(true);var p=BuddyTakeover.Preview(f.E);var r=BuddyTakeover.Apply(f.E,p.stamp,true,true,null,CancellationToken.None);Check(r.cleanupCompleted&&!r.steamVerified&&!r.steamExitRequested&&File.ReadAllText(f.VdfPath)==Vdf,"default fixture mode never discovers or touches real Steam");}
  static void LateChecks(){
   var stale=new Fixture(true);stale.OS.OnShutdown=()=>File.WriteAllText(stale.VdfPath,Vdf.Replace("secretFixture","externally-updated"));stale.Apply(stale.Preview());Check(!BuddyTakeover.Pending(stale.E),"stale exit before any target write needs no recovery or manual overwrite");
   var cancelled=new Fixture();var token=new CancellationTokenSource();var p=cancelled.Preview();var r=BuddyTakeover.Apply(cancelled.E,p.stamp,true,false,(v,t)=>token.Cancel(),token.Token,cancelled.OS);Check(r.status=="cancelled"&&cancelled.OS.Writes==0&&!BuddyTakeover.Pending(cancelled.E),"progress cancellation before first target write has no target effects");
   var added=new Fixture(true);added.OS.OnShutdown=()=>File.WriteAllText(Path.Combine(added.E.Game,"ProjectZomboid32.json"),"{\"vmArgs\":[\"-Xmx2g\"]}");r=added.Apply(added.Preview());Check(!r.cleanupCompleted&&added.OS.Writes==0,"post-exit new game config invalidates preview before writes");
   var race=new Fixture();race.OS.OnReplace=()=>{if(race.OS.Writes==1)File.WriteAllText(race.E.Config,"foreign-exact-atomic-boundary");};r=race.Apply(race.Preview());Check(!r.cleanupCompleted&&File.ReadAllText(race.E.Config)=="foreign-exact-atomic-boundary","atomic replacement race retains exact foreign bytes");
  }
  static Fixture CrashFixture(bool steam){var f=new Fixture(steam);string exe=Process.GetCurrentProcess().MainModule.FileName;using(var child=Process.Start(new ProcessStartInfo(exe,(steam?"--buddy-steam-crash":"--buddy-crash")+" \""+f.Root+"\""){UseShellExecute=false,CreateNoWindow=true})){Check(child.WaitForExit(20000)&&child.ExitCode==73,"isolated interruption leaves durable transaction evidence");}return f;}
  static void CompensationRace(){
   var f=new Fixture();
   f.OS.OnReplace=()=>{if(f.OS.Writes==1)File.WriteAllText(f.E.Config,"foreign-edit-one");if(f.OS.Writes==2)File.WriteAllText(f.E.Config,"foreign-edit-two");};
   var result=f.Apply(f.Preview());
   Check(File.ReadAllText(f.E.Config)=="foreign-edit-two","compensation never leaves the newest foreign bytes overwritten by older foreign bytes");
   Check(result.status=="recoveryRequired"&&result.recoveryPending&&!result.rollbackCompleted,"two-writer compensation conflict stays pending");
   var stage=Directory.GetDirectories(f.E.Game,".ob-*").Single();
   Check(Directory.GetFiles(stage).Any(path=>File.ReadAllText(path)=="foreign-edit-one"),"first displaced foreign update remains private conflict evidence");
   var recovery=BuddyTakeover.Recovery(new Engine(f.E.Game,f.E.User,f.E.Data,true),f.OS);
   Check(recovery.pending&&!recovery.supported&&File.ReadAllText(f.E.Config)=="foreign-edit-two","fresh recovery scan preserves newest foreign target and refuses stale restoration");
   var sameSize=new Fixture();byte[] newest=null;
   sameSize.OS.OnReplace=()=>{if(sameSize.OS.Writes==1)File.WriteAllText(sameSize.E.Config,"first-external-update");if(sameSize.OS.Writes==2){newest=Enumerable.Repeat((byte)'x',File.ReadAllBytes(sameSize.E.Config).Length).ToArray();File.WriteAllBytes(sameSize.E.Config,newest);}};
   result=sameSize.Apply(sameSize.Preview());
   Check(result.recoveryPending&&newest.SequenceEqual(File.ReadAllBytes(sameSize.E.Config)),"exclusive compensation compares exact bytes rather than only file length");
   var filled=new Fixture();
   filled.OS.OnReplace=()=>{if(filled.OS.Writes==1)File.WriteAllText(filled.E.Config,"foreign-before-correction");};
   filled.OS.OnMoveAbsent=(source,target)=>File.WriteAllText(target,"newest-foreign-fills-vacant-name");
   result=filled.Apply(filled.Preview());
   Check(result.recoveryPending&&File.ReadAllText(filled.E.Config)=="newest-foreign-fills-vacant-name","writer filling corrective rename gap stays current because installation cannot overwrite");
   stage=Directory.GetDirectories(filled.E.Game,".ob-*").Single();
   Check(File.ReadAllText(Path.Combine(stage,"old"))=="foreign-before-correction"&&File.ReadAllText(Path.Combine(stage,"newer"))=="{\"vmArgs\":[\"-Xmx8g\",\"-agentlib:zbNative\"],\"custom\":42}","failed no-overwrite correction retains foreign candidate and retired own bytes");
   var interrupted=new Fixture();
   interrupted.OS.OnReplace=()=>{if(interrupted.OS.Writes==1)File.WriteAllText(interrupted.E.Config,"foreign-preserved-before-move-fault");};
   interrupted.OS.OnMoveAbsent=(source,target)=>{throw new IOException("fixture no-overwrite move failure");};
   result=interrupted.Apply(interrupted.Preview());
   recovery=BuddyTakeover.Recovery(new Engine(interrupted.E.Game,interrupted.E.User,interrupted.E.Data,true),interrupted.OS);
   stage=Directory.GetDirectories(interrupted.E.Game,".ob-*").Single();
   Check(result.recoveryPending&&recovery.pending&&!recovery.supported&&!File.Exists(interrupted.E.Config)&&File.ReadAllText(Path.Combine(stage,"old"))=="foreign-preserved-before-move-fault"&&File.Exists(Path.Combine(stage,"newer")),"move failure preserves complete private evidence and requires explicit manual recovery");
  }
  static void RecoveryBoundaries(){
   var f=CrashFixture(true);var state=BuddyTakeover.Recovery(f.E,f.OS);Check(state.pending&&state.supported&&state.requiresSteamExit,"Steam recovery identifies separate exit consent");var cancelled=BuddyTakeover.Recover(f.E,state.stamp,false,false,null,CancellationToken.None,f.OS);Check(cancelled.status=="cancelled"&&cancelled.recoveryPending,"cancelled recovery still truthfully reports pending");var unconfirmed=BuddyTakeover.Recover(f.E,state.stamp,true,false,null,CancellationToken.None,f.OS);Check(unconfirmed.status=="confirmationRequired"&&unconfirmed.recoveryPending&&f.OS.Shutdowns==0,"recovery exit approval remains pending with no process effects");
   f.OS.Account=54321;Check(!BuddyTakeover.Recovery(f.E,f.OS).supported,"other account cannot authorize recorded Steam recovery");f.OS.Account=12345;state=BuddyTakeover.Recovery(f.E,f.OS);var result=BuddyTakeover.Recover(f.E,state.stamp,true,true,null,CancellationToken.None,f.OS);Check(result.status=="recovered"&&!result.recoveryPending&&f.OS.Shutdowns==1&&f.OS.Reopens==1&&File.ReadAllText(f.VdfPath)==Vdf&&File.ReadAllText(f.E.Config)==Dirty,"confirmed same-account recovery restores both files and requests same-client reopen");
   var stale=CrashFixture(false);state=BuddyTakeover.Recovery(stale.E,stale.OS);File.WriteAllText(stale.E.Config,"foreign-after-recovery-preview");result=BuddyTakeover.Recover(stale.E,state.stamp,true,true,null,CancellationToken.None,stale.OS);Check(result.recoveryPending&&File.ReadAllText(stale.E.Config)=="foreign-after-recovery-preview"&&stale.OS.Writes==0,"stale recovery does not overwrite external current bytes");
   var tampered=CrashFixture(false);string journal=Directory.GetFiles(Path.Combine(tampered.E.Data,"backups"),"pending.json",SearchOption.AllDirectories).Single();var record=new JavaScriptSerializer().Deserialize<BuddyTakeover.Record>(File.ReadAllText(journal));record.entries[0].target=Path.Combine(tampered.Root,"foreign.json");File.WriteAllText(journal,new JavaScriptSerializer().Serialize(record));Check(!BuddyTakeover.Recovery(tampered.E,tampered.OS).supported&&BuddyTakeover.Pending(tampered.E),"tampered journal cannot choose arbitrary target paths");
   var safeCancel=CrashFixture(false);state=BuddyTakeover.Recovery(safeCancel.E,safeCancel.OS);var token=new CancellationTokenSource();safeCancel.OS.OnReplace=()=>token.Cancel();result=BuddyTakeover.Recover(safeCancel.E,state.stamp,true,true,null,token.Token,safeCancel.OS);Check(result.status=="cancelled"&&!result.recoveryPending&&File.ReadAllText(safeCancel.E.Config)==Dirty,"cancellation during recovery finishes safe rollback before reporting cancelled");
  }
  static void Interrupted(){var f=new Fixture();string exe=Process.GetCurrentProcess().MainModule.FileName;using(var child=Process.Start(new ProcessStartInfo(exe,"--buddy-crash \""+f.Root+"\""){UseShellExecute=false,CreateNoWindow=true})){Check(child.WaitForExit(20000)&&child.ExitCode==73,"fixture process interruption occurs after real atomic write");}var restarted=new Engine(f.E.Game,f.E.User,f.E.Data,true);var state=BuddyTakeover.Recovery(restarted,f.OS);Check(state.pending&&state.supported&&!state.requiresSteamExit,"reconstructed service offers explicit interrupted recovery");var before=File.ReadAllBytes(f.E.Config);Check(BuddyTakeover.Recover(restarted,state.stamp,false,false,null,CancellationToken.None,f.OS).status=="cancelled"&&before.SequenceEqual(File.ReadAllBytes(f.E.Config)),"recovery false consent is read-only");var r=BuddyTakeover.Recover(restarted,state.stamp,true,false,null,CancellationToken.None,f.OS);Check(r.status=="recovered"&&!BuddyTakeover.Pending(restarted)&&File.ReadAllText(f.E.Config)==Dirty,"explicit recovery restores interrupted original bytes");}
  public static void Run(){foreach(var test in new Action[]{UnknownScope,Consent,GameOnly,Flush,Stale,ExitFailure,Guards,Rollback,Reopen,Defaults,Interrupted,LateChecks,RecoveryBoundaries,CompensationRace})test();Console.WriteLine("BUDDY TAKEOVER PASSED");}
  public static int Main(string[] args){try{if(args.Length==1&&args[0]=="--unknown"){UnknownScope();return 0;}if(args.Length==2&&(args[0]=="--buddy-crash"||args[0]=="--buddy-steam-crash")){if(!Path.GetFullPath(args[1]).StartsWith(Path.GetFullPath(LauncherTestPaths.Root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return 75;bool steam=args[0]=="--buddy-steam-crash";var f=new Fixture(steam,args[1]);f.OS.Crash=true;f.OS.CrashAt=steam?2:1;f.Apply(f.Preview());return 74;}if(args.Length==1&&args[0]=="--compensation"){CompensationRace();return 0;}if(args.Length==1&&args[0]=="--recovery"){RecoveryBoundaries();return 0;}if(args.Length==1&&args[0]=="--late"){LateChecks();return 0;}if(args.Length==1&&args[0]=="--all-red"){int failed=0;foreach(var test in new Action[]{UnknownScope,Consent,GameOnly,Flush,Stale,ExitFailure,Guards,Rollback,Reopen,Defaults,Interrupted}){try{test();}catch(Exception e){failed++;Console.WriteLine(test.Method.Name+": "+e.Message);}}return failed==0?0:1;}Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 }
